import sys
M=1000000007
def f(n):
    a,b=0,1
    for bit in bin(n)[2:]:
        c=a*((b<<1)-a)%M
        d=(a*a+b*b)%M
        if bit=='1':
            a=d;b=(c+d)%M
        else:
            a=c;b=d
    return a
def main():
    print("\n".join(str(f(int(x))) for x in sys.stdin.read().split()))
main()
